#include <vector>
#include <string>

/**
 * A small ring buffer used by the audio decoder.
 */
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), count_(0) {}

    void push(float sample) {
        data_[head_] = sample;
        head_ = (head_ + 1) % data_.size();
        if (count_ < data_.size()) {
            ++count_;
        }
    }

    float mean() const {
        float total = 0.0f;
        for (std::size_t i = 0; i < count_; ++i) {
            total += data_[i];
        }
        return count_ ? total / count_ : 0.0f;
    }

private:
    std::vector<float> data_;
    std::size_t head_;
    std::size_t count_;
};
